import{_ as l,l as i,o as e,c as s,v as t,p as n,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"边缘计算","description":"","frontmatter":{"title":"边缘计算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/edge-compute.md","filePath":"cs/edge-compute.md","lastUpdated":1789023840000}'),h={name:"cs/edge-compute.md"};function P(_,a,m,E,u,T){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="边缘计算" tabindex="-1">边缘计算 <a class="header-anchor" href="#边缘计算" aria-label="Permalink to &quot;边缘计算&quot;">​</a></h1><div class="epigraph"><p>把函数或小服务放到 POP，减 RTT 与回源；状态与一致性比缓存对象难，失败域跟着边缘走。</p><footer>—— 据 CDN 边缘函数实践；RFC 9110 对照；主干任播课整理</footer></div><p><a href="/cs/cdn-cache-hierarchy">上一课</a> 缓存的是表示。缺口是<strong>在边缘跑逻辑</strong>：A/B、鉴权、改写、小 API。本课不把 L4/L7 LB 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存解决 GET 不变对象。个性化、Bot 校验、聚合要计算。边缘函数：请求到达 POP 即执行，近用户，冷启动与隔离是代价。状态：会话若在中心 DB，边缘仍要回源，延迟优势缩水。与 5G 边缘 MEC 同类动机，一层 Web，一层 RAN。不是把数据中心 Clos 搬到每座城。</p><p>不要把边缘写成「无限小云」。</p><p><span class="marginnote">各家 Workers 是实现。本课钉位置与状态边界。</span></p><h3 id="算得近仍怕状态" tabindex="-1">算得近仍怕状态 <a class="header-anchor" href="#算得近仍怕状态" aria-label="Permalink to &quot;算得近仍怕状态&quot;">​</a></h3><p>无状态函数最赚 RTT。会话在中心 DB 则优势缩水。失败域随 POP。不是每城一座 Clos。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：纯缓存 / 边缘函数 / 中心源。画：DNS → POP 计算 → 可选源。与 PTP：边缘时间仍靠 NTP 够用。</p>',11)),(e(),n(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20POP%5B%22%E8%BE%B9%E7%BC%98%E6%89%A7%E8%A1%8C%22%5D%0A%20%20POP%20--%3E%20CACHE%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%22%5D%0A%20%20POP%20--%3E%20ORIGIN%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E5%9B%9E%E6%BA%90%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GeoDNS/任播决定哪个 POP。Cookie 会话粘到 POP 或用全局存储。QUIC CID 要在任播集群可路由。gRPC 在边缘要终止 H2。失败：某 POP 代码坏只伤一区域，但版本发布要全网。</p><p>安全：多租隔离，不写逃逸。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 wasm 运行时的全部。L4/L7 负载均衡是下一课。后课默认：边缘计算换 RTT，状态仍是难题。</p><p>把强一致账本放边缘会变成分布式事务课，不在本课展开。</p><p>上一课留下的缺口在本课收口；「边缘计算」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/l4-l7-load-balancing">L4 / L7 负载均衡</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计算随请求到 POP，减 RTT。</li><li>无状态最赚；有状态易回源。</li><li>与缓存层次互补。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：边缘函数实践；HTTP 语义对照。</li></ul>',10))])}const f=l(h,[["render",P]]);export{C as __pageData,f as default};
